 def test_11_concurrent_confirmation_creates_one_existing_crm_order(self):
  from concurrent.futures import ThreadPoolExecutor
  r,o=self.offer();x=self.cp(f'offers/{o["id"]}/accept',s=self.customer,version=int(o['version']),checksum=o['checksum'],confirm=True);self.assertEqual(x.status_code,200,x.text);r=self.cg('requests/'+str(r['id']),self.customer).json()['record'];account=int(self.f.sql('SELECT id FROM nd_customer_accounts WHERE customer_id=? LIMIT 1',params=[self.customer_id])[0]['id'])
  def confirm(_):
   code='require $v["root"]."/private/app.php";require $v["root"]."/private/catalog/routes.php";echo json_encode(cat_confirm(["type"=>"customer","id"=>$v["account"],"customer_id"=>$v["customer"]],$v["id"],["version"=>$v["version"],"confirm"=>true,"request_key"=>$v["key"]]));'
   return json.loads(self.f.php_eval(code,{'root':str(self.f.path),'account':account,'customer':self.customer_id,'id':r['id'],'version':int(r['version']),'key':secrets.token_hex(32)}))
  with ThreadPoolExecutor(max_workers=2) as pool:out=list(pool.map(confirm,range(2)))
  self.assertTrue(all(x['ok'] for x in out));self.assertEqual(out[0]['order_id'],out[1]['order_id']);self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_orders WHERE deal_id=?',params=[self.cg('requests/'+str(r['id'])).json()['record']['deal_id']])[0]['n'],1)
