  r,o=self.offer();x=self.cp(f'offers/{o["id"]}/accept',s=self.customer,version=int(o['version']),checksum=o['checksum'],confirm=True);self.assertEqual(x.status_code,200,x.text);r=self.cg('requests/'+str(r['id']),self.customer).json()['record'];x=self.cp(f'requests/{r["id"]}/confirm',s=self.customer,version=int(r['version']),confirm=True);self.assertEqual(x.status_code,200,x.text);oid=x.json()['order_id'];amount=self.f.sql('SELECT total_amount FROM nd_orders WHERE id=?',params=[oid])[0]['total_amount'];c=json.loads(json.dumps(self.f.config))
