   self.f.config.update(billing_enabled=True,billing_merchant={'approved':True,'legal_name':'Синтетический исполнитель','registration':'Только тест','address':'Тестовый адрес','tax_treatment':'Только тестовая трактовка','payment_instructions':'Тестовые условия','retention_policy':'Тестовый срок','number_prefix':'TEST'});self.f.write_config();url=self.base+'/api.php?r=crm/billing/';x=self.owner.post(url+'invoices',json={'request_key':secrets.token_hex(32),'customer_id':self.customer_id,'order_id':oid,'due_on':(datetime.now(timezone.utc)+timedelta(days=3)).strftime('%Y-%m-%d'),'lines':[{'description':'Синтетический результат каталога','quantity':'1','unit_price':amount}]});self.assertEqual(x.status_code,200,x.text);invoice=x.json()['record'];x=self.owner.post(url+f'invoices/{invoice["id"]}/issue',json={'request_key':secrets.token_hex(32),'version':int(invoice['version']),'confirm':True});self.assertEqual(x.status_code,200,x.text);customer_url=self.base+'/customer-api.php?r=billing/invoices/'+str(invoice['id']);self.assertEqual(self.customer.get(customer_url).status_code,200);self.assertEqual(self.stranger.get(customer_url).status_code,404);self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_payment_attempts')[0]['n'],0)
