 def test_19_owner_prelinked_order_never_creates_second_order(self):
  r=self.submitted();existing=self.insert("INSERT INTO nd_orders(customer_id,number,title,total_amount,status) VALUES (?,?,'Заказ, созданный владельцем','100.00','confirmed')",'nd_orders',[self.customer_id,'OWNER-'+secrets.token_hex(8)]);self.f.sql('UPDATE nd_projects SET order_id=?,version=version+1 WHERE id=?',params=[existing,r['project_id']]);x=self.cp(f'requests/{r["id"]}/estimate');self.assertEqual(x.status_code,200,x.text);r=self.cg('requests/'+str(r['id'])).json()['record'];r,o=self.offer(r);x=self.cp(f'offers/{o["id"]}/accept',s=self.customer,version=int(o['version']),checksum=o['checksum'],confirm=True);self.assertEqual(x.status_code,200,x.text);r=self.cg('requests/'+str(r['id']),self.customer).json()['record'];x=self.cp(f'requests/{r["id"]}/confirm',s=self.customer,version=int(r['version']),confirm=True);self.assertEqual(x.status_code,409,x.text);self.assertIn('Проект уже связан',x.text);self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_orders WHERE deal_id=?',params=[r['deal_id']])[0]['n'],0);self.assertEqual(int(self.f.sql('SELECT order_id FROM nd_projects WHERE id=?',params=[r['project_id']])[0]['order_id']),existing)

